}

.topbar::after {
  content: '';
  position: absolute;
  left: var(--sidebar-width);
  right: 0;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, #4F9CF95e 36%, #A7CEFC 50%, transparent 82%);
  background-size: 200% 100%;
  animation: topbar-signal 12s linear infinite;
  pointer-events: none;
}

.demo-strip {
  background: #FFFFFFcc;
  border-color: #FFFFFF;
}

.hero-banner {
  min-height: 342px;
  border: 1px solid #A7CEFC66;
  border-radius: 20px;
  background: linear-gradient(115deg, #212529, #212529 52%, #37A3FF);
  background-size: 180% 180%;
  animation: hero-current 18s ease-in-out infinite alternate;
  box-shadow: 0 22px 64px #21252924;
}

.hero-motion-paused,
.hero-motion-paused::after,
.hero-motion-paused .hero-art::after,
.hero-motion-paused .hero-art .resume-document {
  animation-play-state: paused !important;
}

.hero-banner::before {
  content: '';
  position: absolute;
  z-index: 0;
  inset: 0;
  opacity: 0.3;
  background-image:
    linear-gradient(#FFFFFF0a 1px, transparent 1px),
    linear-gradient(90deg, #FFFFFF0a 1px, transparent 1px),
    radial-gradient(circle at 14% 26%, #FFFFFF 0 1px, transparent 1.7px),
    radial-gradient(circle at 38% 78%, #A7CEFC 0 1px, transparent 1.7px),
    radial-gradient(circle at 61% 17%, #FFFFFF 0 1px, transparent 1.7px);
  background-size: 48px 48px, 48px 48px, 100% 100%, 100% 100%, 100% 100%;
  mask-image: linear-gradient(90deg, #212529 0%, #212529 60%, transparent 90%);
  pointer-events: none;
}

.hero-banner::after {
  content: '';
  position: absolute;
  z-index: 0;
  width: min(54vw, 690px);
  aspect-ratio: 1.75;
  right: 1.5%;
  top: 4%;
  border: 1px solid #FFFFFF26;
  border-radius: 50%;
  box-shadow:
    0 0 0 14px #FFFFFF08,
    0 0 0 35px #FFFFFF06,
    0 0 80px #A7CEFC1f;
  transform: rotate(-13deg);
  animation: orbit-drift 48s linear infinite;
  pointer-events: none;
}

.ribbon-backdrop {
  background: transparent;
}

.ribbon-backdrop::before,
.ribbon-backdrop::after {
  border-color: #A7CEFC;
  opacity: 0.17;
}

.ribbon-backdrop::after {
  border-color: #FFFFFF;
  opacity: 0.1;
}

.ribbon-canvas {
  mix-blend-mode: screen;
}

.hero-content {
  z-index: 1;
  padding: 40px;
}

.hero-content h2 {
  color: #FFFFFF;
  font-size: clamp(30px, 3vw, 42px);
  line-height: 1.3;
  font-weight: 700;
  text-shadow: 0 2px 22px #21252962;
}

.hero-content > p {
  color: #FFFFFF;
}

.hero-buttons .button-primary {
  color: #212529;
  background: linear-gradient(120deg, #FFFFFF 0%, #FFFFFF 48%, #A7CEFC 100%);
  border-color: #FFFFFF99;
  box-shadow: 0 8px 26px #21252966;
}

.hero-buttons .button-primary:hover {
  background: #FFFFFF;
}

.hero-text-button,
.hero-footnote {
  color: #FFFFFF;
}

.hero-text-button:hover {
  color: #FFFFFF;
}

.hero-footnote > svg {
  color: #A7CEFC;
}

.hero-art {
  z-index: 1;
  height: 310px;
  margin: 16px 20px 16px 0;
  padding: 20px 24px;
  overflow: hidden;
  border: 1px solid #FFFFFF55;
  border-radius: 15px;
  background: linear-gradient(145deg, #FFFFFF, #A7CEFC);
  box-shadow: 0 18px 52px #21252959;
}

.hero-art::after {
  content: '';
  position: absolute;
  z-index: 0;
  left: 8%;
  right: 8%;
  top: 33px;
  height: 2px;
  background: linear-gradient(90deg, transparent, #4F9CF9, #FFFFFF, transparent);
  filter: drop-shadow(0 0 6px #4F9CF9);
  opacity: 0.55;
  animation: scan-line 6s ease-in-out infinite;
  pointer-events: none;
}

.hero-art-label {
  z-index: 1;
  color: #37A3FF;
}

.hero-art .resume-document {
  position: relative;
  z-index: 1;
  box-shadow: 0 18px 40px #37A3FF30;
  animation: document-hover 8s ease-in-out infinite;
}

.motion-control {
  color: #FFFFFF;
  background: #212529dd;
  border-color: #FFFFFF75;
  backdrop-filter: blur(10px);
}

.motion-control:hover {
  color: #FFFFFF;
  background: #37A3FF;
}

.page-heading {
  position: relative;
  padding-bottom: 5px;
}

.page-heading::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: 0;
  width: 72px;
  height: 2px;
  border-radius: 99px;
  background: linear-gradient(90deg, #37A3FF, #A7CEFC, transparent);
}

.page-heading h1 {
  letter-spacing: -0.025em;
}

.panel {
  border-color: #FFFFFF;
  box-shadow: 0 12px 32px #2125290a;
  transition:
    border-color 240ms ease,
    box-shadow 240ms ease,
    transform 240ms var(--ease-out);
}

.job-card,
.library-card,
.preparation-option,
.jd-row,
.stat-card {
  transition:
    border-color 220ms ease,
    box-shadow 220ms ease,
    transform 220ms var(--ease-out),
    background-color 220ms ease;
}

.job-card:hover,
.library-card:hover,
.stat-card:hover {
  border-color: #A7CEFC;
  box-shadow: 0 18px 40px #37A3FF1a;
  transform: translateY(-4px);
}

.soft-banner {
  position: relative;
  overflow: hidden;
  border-color: #FFFFFF;
  background:
    radial-gradient(ellipse at 100% 0%, #FFFFFF57, transparent 22rem),
    linear-gradient(115deg, #FFFFFF, #FFFFFF 64%);
}

.soft-banner::after {
  content: '';
  position: absolute;
  width: 150px;
  height: 150px;
  right: -92px;
  top: -95px;
  border: 1px solid #4F9CF92e;
  border-radius: 50%;
  box-shadow: 0 0 0 12px #4F9CF90a, 0 0 0 26px #4F9CF908;
  pointer-events: none;
}

.stepper .current > span {
  box-shadow: 0 0 0 5px #37A3FF1c, 0 0 24px #37A3FF45;
  animation: step-signal 2.8s ease-in-out infinite;
}

.job-card .company-mark {
  background: linear-gradient(145deg, #FFFFFF, #A7CEFC);
  box-shadow: inset 0 0 0 1px #4F9CF91a;
}

.job-card .tag-match {
  border-color: #A7CEFC;
  box-shadow: 0 0 0 2px #4F9CF90d;
}

.resume-card {
  border-color: #FFFFFF;
  box-shadow: 0 12px 28px #21252912;
}

.resume-card:hover {
  border-color: #A7CEFC;
  box-shadow: 0 20px 44px #37A3FF25;
}

.feature-card {
  border-radius: 12px;
  padding-inline: 12px;
  transition:
    transform 240ms var(--ease-out),
    background-color 240ms ease,
    box-shadow 240ms ease;
}

.feature-card:hover {
  background: #FFFFFFb5;
  box-shadow: 0 14px 30px #37A3FF12;
  transform: translateX(4px);
}

.feature-card .feature-icon {
  border-radius: 10px;
  background: #FFFFFF;
  color: #37A3FF;
}

.dashboard .resume-card .resume-thumbnail,
.library-preview {
  background:
    radial-gradient(ellipse at 100% 0%, #A7CEFC4a, transparent 65%),
    #FFFFFF;
}

.auth-page {
  background:
    radial-gradient(ellipse at 8% 15%, #37A3FF52, transparent 34rem),
    linear-gradient(90deg, #212529 0%, #212529 48%, #FFFFFF 48.1%, #FFFFFF 100%);
}

.auth-story {
  position: relative;
  overflow: hidden;
  background: transparent;
  color: #FFFFFF;
}

.auth-story h1,
.auth-story p,
.auth-story li,
.auth-story > small {
  color: #FFFFFF;
}

.auth-story p,
.auth-story > small {
  color: #A7CEFC;
}

.auth-story li svg {
  color: #A7CEFC;
}

.auth-story::after {
  content: '';
  position: absolute;
  width: 360px;
  height: 360px;
  right: -230px;
  bottom: -180px;
  border: 1px solid #FFFFFF3b;
  border-radius: 50%;
  box-shadow: 0 0 0 20px #FFFFFF0a, 0 0 0 42px #FFFFFF08;
  pointer-events: none;
}

.auth-form {
  padding: clamp(24px, 4vw, 40px);
  border: 1px solid #FFFFFF;
  border-radius: 22px;
  background: #FFFFFF;
  border-color: #FFFFFF;
  box-shadow: 0 26px 80px #2125291f;
}

.button-primary:not(:disabled) {
  box-shadow: 0 6px 18px #37A3FF22;
}

.button-primary:not(:disabled):hover {
  box-shadow: 0 10px 26px #37A3FF3a;
}

@keyframes topbar-signal {
  to {
    background-position: 200% 0;
  }
}

@keyframes hero-current {
  from {
    background-position: 0% 40%;
  }
  to {
    background-position: 100% 60%;
  }
}

@keyframes orbit-drift {
  to {
    transform: rotate(347deg);
  }
}

@keyframes document-hover {
  0%,
  100% {
    transform: translateY(0) rotate(-0.4deg);
  }
  50% {
    transform: translateY(-7px) rotate(0.4deg);
  }
}

@keyframes scan-line {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.22;
  }
  50% {
    transform: translateY(245px);
    opacity: 0.8;
  }
}

@keyframes step-signal {
  0%,
  100% {
    box-shadow: 0 0 0 4px #37A3FF15, 0 0 14px #37A3FF2e;
  }
  50% {
    box-shadow: 0 0 0 7px #37A3FF1c, 0 0 25px #37A3FF59;
  }
}

@media (max-width: 960px) {
  .sidebar {
    box-shadow: 20px 0 56px #21252940;
  }

  .topbar::after {
    left: 0;
  }

  .hero-banner {
    min-height: 0;
  }

  .hero-content {
    padding: 28px 26px;
  }

  .hero-art {
    height: 220px;
    margin: 0 18px 18px;
    border-left: 1px solid #FFFFFF55;
    border-radius: 13px;
  }

  .hero-art .resume-document {
    animation-duration: 10s;
  }
}

@media (max-width: 600px) {
  .hero-banner::after {
    width: 88vw;
    right: -20%;
    top: 24%;
  }

  .hero-content {
    padding: 26px 20px;
  }

  .hero-content h2 {
    font-size: 28px;
  }

  .hero-art {
    height: 188px;
    margin: 0 12px 12px;
    padding: 16px;
  }

  .sidebar-note {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .topbar::after,
  .hero-banner,
  .hero-banner::after,
  .hero-art::after,
  .hero-art .resume-document,
  .stepper .current > span {
    animation: none !important;
  }

  .brand-icon,
  .nav-link,
  .sidebar-utility .nav-link,
  .panel,
  .job-card,
  .library-card,
  .stat-card,
  .feature-card {
    transition: none !important;
  }

  .brand:hover .brand-icon,
  .nav-link:hover,
  .sidebar-utility .nav-link:hover,
  .job-card:hover,
  .library-card:hover,
  .stat-card:hover,
  .feature-card:hover {
    transform: none !important;
  }
}

@media print {
  .sidebar,
  .topbar,
  .demo-strip,
  .motion-control,
  .hero-art::after {
    animation: none !important;
    box-shadow: none !important;
  }
}

/* Resume template catalog: each option carries through to the editor and export. */
.template-picker-trigger {
  margin-top: var(--space-md);
}

.selected-template-summary {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: var(--space-sm);
  color: var(--color-ink-2);
  font-size: var(--text-xs);
}

.selected-template-summary > svg {
  color: var(--color-accent-text);
}

.selected-template-summary strong {
  color: var(--color-accent-text);
}

.selected-template-summary span {
  color: var(--color-muted);
}

.template-picker > p {
  color: var(--color-ink-2);
  font-size: var(--text-sm);
  margin-bottom: var(--space-md);
}

.template-category-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.template-category-tabs button {
  min-height: 36px;
  padding: 0 var(--space-md);
  border: 1px solid var(--color-rule);
  border-radius: var(--radius-pill);
  background: var(--color-paper);
  color: var(--color-ink-2);
  font-size: var(--text-xs);
}

.template-category-tabs button:hover,
.template-category-tabs button.active {
  color: var(--color-accent-text);
  border-color: #A7CEFC;
  background: var(--color-accent-soft);
}

.template-gallery {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-sm);
  max-height: min(58vh, 520px);
  overflow-y: auto;
  padding: 2px 3px 4px 2px;
}

.template-gallery-item {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--color-rule);
  border-radius: var(--radius-control);
  background: var(--color-paper);
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms var(--ease-out);
}

.template-gallery-item:hover {
  border-color: #A7CEFC;
  box-shadow: 0 8px 20px #21252916;
  transform: translateY(-2px);
}

.template-gallery-item.selected {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 2px #37A3FF2b;
}

.template-gallery-item > .resume-thumbnail {
  height: 164px;
  padding: var(--space-md) var(--space-xs) 0;
}

.template-gallery-item .thumbnail-paper {
  transform: scale(0.88);
  transform-origin: top center;
}

.template-gallery-copy {
  padding: var(--space-sm);
}

.template-gallery-copy > span,
.template-gallery-copy > small {
  display: block;
  color: var(--color-muted);
  font-size: 11px;
  line-height: 1.55;
}

.template-gallery-copy h3 {
  margin-top: 3px;
  color: var(--color-ink);
  font-size: var(--text-sm);
}

.template-gallery-copy p {
  min-height: 38px;
  margin-top: 4px;
  color: var(--color-ink-2);
  font-size: 11px;
  line-height: 1.6;
}

.template-use-button {
  width: 100%;
  min-height: 34px;
  margin-top: var(--space-xs);
  padding-inline: var(--space-xs);
  font-size: 11px;
}

/* Distinct resume page structures. */
.document-modern .document-heading {
  padding: 14px 18px;
  border: 0;
  border-radius: 5px;
  background: color-mix(in oklab, var(--resume-accent) 9%, white);
}

.document-modern .document-heading h1 {
  color: var(--color-ink);
}

.document-modern .document-section h2 {
  border-bottom: 0;
  border-left: 3px solid var(--resume-accent);
  padding: 2px 0 2px 9px;
}

.document-campus .document-heading {
  text-align: center;
  border-bottom: 3px solid color-mix(in oklab, var(--resume-accent) 70%, white);
}

.document-campus .document-heading h1,
.document-campus .document-role,
.document-campus .document-contact {
  text-align: center;
}

.document-campus .document-section h2 {
  color: color-mix(in oklab, var(--resume-accent) 76%, #37A3FF);
  border-bottom: 1px dashed color-mix(in oklab, var(--resume-accent) 38%, white);
}

.document-academic .document-heading {
  border-bottom: 1px solid #37A3FF;
}

.document-academic .document-heading h1,
.document-academic .document-section h2 {
  color: #37A3FF;
}

.document-academic .document-section h2 {
  border-bottom-color: #37A3FF;
  letter-spacing: 0.04em;
}

.document-creative {
  box-shadow: inset 5px 0 0 var(--resume-accent);
}

.document-creative .document-heading {
  padding: 10px 14px 14px;
  border-bottom: 0;
  background: color-mix(in oklab, var(--resume-accent) 8%, white);
}

.document-creative .document-heading h1 {
  font-size: 2.2em;
}

.document-creative .document-section h2 {
  width: fit-content;
  padding: 0 14px 3px 0;
  border-bottom: 2px solid var(--resume-accent);
}

/* Matching miniature layouts make the chooser preview truthful. */
.thumbnail-modern .thumbnail-heading {
  background: #FFFFFF;
  border: 0;
  border-radius: 2px;
  padding: var(--space-xs);
}

.thumbnail-modern .thumbnail-section b {
  border-left: 2px solid var(--color-accent);
  padding-left: 3px;
}

.thumbnail-campus .thumbnail-heading {
  display: block;
  text-align: center;
  border-bottom: 2px solid #37A3FF;
}

.thumbnail-campus .thumbnail-heading i {
  display: none;
}

.thumbnail-campus .thumbnail-section b {
  color: #37A3FF;
}

.thumbnail-academic .thumbnail-heading {
  border-bottom-color: #37A3FF;
}

.thumbnail-academic .thumbnail-heading strong,
.thumbnail-academic .thumbnail-section b {
  color: #37A3FF;
}

.thumbnail-academic .thumbnail-section b {
  border-bottom: 1px solid #4F9CF9;
  padding-bottom: var(--space-3xs);
}

.thumbnail-creative .thumbnail-paper {
  border-left: 4px solid var(--color-accent);
  padding-left: var(--space-xs);
}

.thumbnail-creative .thumbnail-heading {
  background: #FFFFFF;
  padding: var(--space-2xs);
}

@media (max-width: 760px) {
  .template-gallery {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-height: 55vh;
  }
}

@media (max-width: 420px) {
  .template-gallery {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .template-gallery-item {
    transition: none;
  }
  .template-gallery-item:hover {
    transform: none;
  }
}

/* Presentation refresh: Inspira-style hover controls/upload and purple connected steps.
   Event handlers, API clients and wizard state remain in their original components. */
.app-shell {
  width: 100%;
  max-width: none;
  margin-inline: 0;
}
.app-shell > .sidebar {
  left: 0;
}
.sidebar .nav-link-current,
.sidebar .nav-link-current:hover {
  box-shadow: none;
}
.sidebar .nav-link-current::before {
  content: none;
}
.topbar .breadcrumb,
.topbar .search-input,
.dashboard .journey-panel {
  display: none;
}
.topbar-actions {
  margin-left: auto;
}
.dashboard .dashboard-lower {
  grid-template-columns: minmax(0, 1fr);
}
/* Remove the routine environment banner while retaining existing failure messages. */
.app-main > .demo-strip:not(:has(.storage-error)):not(:has([role='alert'])) {
  display: none;
}
.app-main > .demo-strip > span {
  display: none;
}

/* Single slot: preserve button labels, icons, loading/disabled states and click targets. */
.base-button .button-content {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-xs);
  min-width: 0;
  transition: transform 300ms var(--ease-out);
}
.base-button .button-hover-dot,
.base-button .button-hover-arrow {
  display: none;
  pointer-events: none;
}
.base-button:not(.button-ghost) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  gap: 0;
  padding-inline: 34px;
  border: 1px solid var(--color-rule);
  border-radius: var(--radius-pill);
  background: var(--color-paper);
  color: var(--color-ink);
  box-shadow: none;
  transition: color 300ms ease, border-color 300ms ease;
}
.base-button:not(.button-ghost)::after {
  content: none;
  animation: none;
}
.base-button:not(.button-ghost) .button-hover-dot {
  display: block;
  position: absolute;
  z-index: 1;
  left: 15px;
  top: calc(50% - 4px);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent);
  transform-origin: center;
  transition: transform 440ms cubic-bezier(0.22, 1, 0.36, 1);
}
.base-button:not(.button-ghost) .button-hover-arrow {
  display: block;
  position: absolute;
  z-index: 2;
  top: calc(50% - 9px);
  right: 14px;
  width: 18px;
  height: 18px;
  opacity: 0;
  transform: translateX(14px);
  transition: transform 300ms var(--ease-out), opacity 220ms ease;
}
.base-button:not(.button-ghost):not(:disabled):is(:hover, :focus-visible:not([class*="el-"])) {
  color: var(--color-accent-ink);
  border-color: var(--color-accent);
  background: var(--color-paper);
  box-shadow: none;
  transform: none;
}
.base-button:not(.button-ghost):not(:disabled):is(:hover, :focus-visible:not([class*="el-"])) .button-hover-dot {
  transform: scale(150);
}
.base-button:not(.button-ghost):not(:disabled):is(:hover, :focus-visible:not([class*="el-"])) .button-content {
  transform: translateX(-5px);
  animation: hover-button-label 320ms ease-out both;
}
@keyframes hover-button-label {
  0% { opacity: 1; transform: translateX(0); }
  35% { opacity: 0; transform: translateX(24px); }
  36% { opacity: 0; transform: translateX(-20px); }
  100% { opacity: 1; transform: translateX(-5px); }
}
.base-button:not(.button-ghost):not(:disabled):is(:hover, :focus-visible:not([class*="el-"])) .button-hover-arrow {
  opacity: 1;
  transform: translateX(0);
}
.base-button:not(.button-ghost):disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.base-button:not(.button-ghost)[aria-busy='true'] {
  cursor: progress;
}
.base-button:not(.button-ghost):not(:disabled):active {
  transform: scale(0.98);
}
/* Other existing capsule controls use the same purple fill and inset dot cue. */
.motion-control,
.template-category-tabs button {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: var(--radius-pill);
  padding-inline: 28px 16px;
  transition: color 260ms ease, background-color 260ms ease, border-color 260ms ease;
}
.motion-control::before,
.template-category-tabs button::before {
  content: '';
  position: absolute;
  z-index: -1;
  left: 12px;
  top: calc(50% - 3px);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent);
  pointer-events: none;
  transition: transform 350ms var(--ease-out);
}
.motion-control {
  position: absolute;
}
.motion-control:is(:hover, :focus-visible:not([class*="el-"])),
.template-category-tabs button:is(:hover, :focus-visible:not([class*="el-"]), .active) {
  color: var(--color-accent-ink);
  background: var(--color-paper);
  border-color: var(--color-accent);
}
.motion-control:is(:hover, :focus-visible:not([class*="el-"]))::before,
.template-category-tabs button:is(:hover, :focus-visible:not([class*="el-"]), .active)::before {
  background: var(--color-accent);
  transform: scale(150);
}

/* Element-style steps: circle -> connector -> next circle; reuse current/complete states. */
.stepper {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  align-items: start;
  gap: 0;
  padding: 8px 0 28px;
  margin-bottom: 28px;
  border: 0;
  background: transparent;
}
.stepper > div {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: flex-start;
  gap: 12px;
  padding: 0;
  min-width: 0;
}
.stepper > div:not(:last-child)::after {
  content: '';
  position: absolute;
  top: 16px;
  left: 36px;
  right: 4px;
  height: 2px;
  background: var(--color-rule);
}
.stepper > div.complete::after {
  background: var(--color-accent);
}
.stepper > div > span {
  position: relative;
  z-index: 1;
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  border: 2px solid var(--color-rule);
  border-radius: 50%;
  background: var(--color-paper);
  color: var(--color-muted);
  font-size: 15px;
  font-weight: 600;
  box-shadow: none;
  animation: none;
}
.stepper > div strong {
  display: block;
  color: var(--color-muted);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.5;
}
.stepper > div:is(.current, .complete) > span {
  border-color: var(--color-accent);
  color: var(--color-accent);
  background: var(--color-paper);
  animation: none;
  box-shadow: none;
}
.stepper > div.current strong {
  color: var(--color-accent-text);
  font-weight: 600;
}
.stepper > div.complete strong {
  color: var(--color-accent-text);
}

/* Inspira-style file surface: light grid, floating tile, and dashed target. */
.wizard-panel .upload-zone {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  align-content: center;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: 292px;
  gap: 8px;
  padding: 28px 20px;
  border: 1px solid var(--color-rule);
  border-radius: 16px;
  color: var(--color-ink);
  background: var(--color-paper);
  perspective: 800px;
  transition: border-color 250ms ease;
}
.wizard-panel .upload-zone::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 0;
  background-image: linear-gradient(var(--color-rule) 1px, transparent 1px), linear-gradient(90deg, var(--color-rule) 1px, transparent 1px);
  background-size: 24px 24px;
  opacity: 0.42;
  mask-image: radial-gradient(ellipse at 50% 65%, #212529 8%, transparent 74%);
}
.wizard-panel .upload-zone::after {
  content: '';
  position: relative;
  z-index: 0;
  grid-area: 3 / 1;
  align-self: center;
  width: 112px;
  height: 112px;
  margin-top: 20px;
  border: 1px dashed #A7CEFC;
  border-radius: 12px;
  opacity: 0;
  transition: opacity 300ms ease;
}
.wizard-panel .upload-zone > strong {
  font-size: 16px;
  font-weight: 600;
}
.wizard-panel .upload-zone > small {
  display: block;
  max-width: 100%;
  font-size: 12px;
  line-height: 1.7;
  color: var(--color-muted);
}
.upload-card {
  position: relative;
  z-index: 1;
  grid-area: 3 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 112px;
  height: 112px;
  margin-top: 20px;
  border: 1px solid var(--color-rule);
  border-radius: 12px;
  color: var(--color-accent);
  background: #FFFFFF;
  box-shadow: 0 5px 18px #21252914, 0 1px 3px #2125290a;
  transform: none;
  pointer-events: none;
  transition: transform 350ms var(--ease-out), box-shadow 350ms ease, opacity 350ms ease;
}
.wizard-panel .upload-zone:is(:hover, :focus-within) {
  border-color: #A7CEFC;
}
.wizard-panel .upload-zone:is(:hover, :focus-within) .upload-card {
  transform: translate(20px, -20px);
  opacity: 0.9;
  box-shadow: 0 18px 32px #37A3FF24;
}
.wizard-panel .upload-zone:is(:hover, :focus-within)::after {
  opacity: 1;
}
.wizard-panel .upload-zone > input:not([class*="el-"]) {
  z-index: 3;
}
@media (max-width: 640px) {
  .stepper {
    padding-bottom: 20px;
    margin-bottom: 20px;
  }
  .stepper > div {
    gap: 10px;
  }
  .stepper > div strong {
    font-size: 12px;
    padding-right: 4px;
  }
  .stepper > div > span {
    flex-basis: 30px;
    width: 30px;
    height: 30px;
    font-size: 13px;
  }
  .stepper > div:not(:last-child)::after {
    top: 14px;
    left: 32px;
  }
  .wizard-panel .upload-zone {
    padding-inline: 16px;
    min-height: 240px;
  }
  .base-button:not(.button-ghost) {
    padding-inline: 30px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .base-button .button-content,
  .base-button .button-hover-dot,
  .base-button .button-hover-arrow,
  .upload-card,
  .motion-control,
  .template-category-tabs button {
    transition: none;
    animation: none;
  }
  .wizard-panel .upload-zone:is(:hover, :focus-within) .upload-card {
    transform: none;
  }
}

