  margin: auto;
  padding: var(--space-8) var(--space-8) var(--space-xl);
}
.page-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-5);
  margin-bottom: var(--space-lg);
}
.page-heading h1 {
  font-size: 26px;
  font-weight: 650;
  line-height: 1.5;
  color: var(--color-ink);
}
.page-heading p {
  margin-top: var(--space-xs);
  color: var(--color-muted);
  font-size: var(--text-sm);
  line-height: 1.8;
}
.page-heading-actions {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  flex-wrap: wrap;
  justify-content: flex-end;
}
.demo-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
  background: var(--color-paper-2);
  border-bottom: 1px solid var(--color-rule);
  padding: var(--space-xs) var(--space-8);
  color: var(--color-ink-2);
  font-size: var(--text-xs);
  line-height: 1.6;
}
.demo-strip > span {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}
.demo-strip small {
  font-size: var(--text-xs);
  color: var(--color-muted);
}
.panel {
  min-width: 0;
  background: var(--color-paper);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: var(--space-lg);
}
.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-md);
  margin-bottom: var(--space-lg);
}
.stat-card {
  padding: var(--space-5) var(--space-lg);
  border: 1px solid var(--color-rule);
  border-radius: 11px;
  background: var(--color-paper-2);
}
.stat-card > span {
  font-size: var(--text-sm);
  color: var(--color-muted);
  font-variant-numeric: tabular-nums;
}
.stat-card > strong {
  display: block;
  font-size: 30px;
  color: var(--color-ink-2);
  margin-top: var(--space-xs);
  font-weight: 600;
}
.stat-card small {
  font-size: var(--text-xs);
  color: var(--color-muted);
  font-weight: 400;
  margin-left: var(--space-sm);
  font-variant-numeric: tabular-nums;
}
.list-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
  flex-wrap: wrap;
  margin-bottom: var(--space-5);
}
.list-title {
  display: flex;
  gap: var(--space-xs);
  align-items: center;
  font-size: 16px;
  font-weight: 600;
  color: var(--color-ink-2);
  line-height: 1.7;
}
.tabs {
  display: flex;
  gap: var(--space-2xs);
  flex-wrap: wrap;
  padding: var(--space-2xs);
  background: var(--color-paper);
  border-radius: 8px;
  width: fit-content;
}
.tabs > button {
  padding: var(--space-xs) var(--space-md);
  background: none;
  border: 0;
  color: var(--color-muted);
  font-size: var(--text-sm);
  border-radius: 6px;
  white-space: nowrap;
}
.tabs > button.active {
  background: var(--color-paper);
  color: var(--color-ink-2);
  box-shadow: none;
  font-weight: 600;
}
.toolbar-fields {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  flex-wrap: wrap;
}
.toolbar-fields input:not([class*="el-"]),
.toolbar-fields select:not([class*="el-"]),
.plain-input,
.inline-search {
  border: 1px solid var(--color-rule);
  border-radius: 7px;
  padding: var(--space-xs) var(--space-sm);
  font-size: var(--text-sm);
  color: var(--color-ink-2);
  background: var(--color-paper);
  min-width: 0;
}
.inline-search {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}
.inline-search input:not([class*="el-"]) {
  border: 0;
  background: none;
  font-size: var(--text-sm);
  min-width: 0;
  color: inherit;
  outline: 0;
}
.inline-search:focus-within {
  outline: 2px solid var(--color-focus);
}
.pill {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2xs);
  border-radius: 5px;
  background: var(--color-paper-2);
  color: var(--color-ink-2);
  padding: var(--space-2xs) var(--space-xs);
  font-size: var(--text-xs);
  font-weight: 400;
  line-height: 1.4;
}
.pill.green {
  color: var(--color-success);
  background: var(--color-paper);
}
.library-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-5);
}
.library-card {
  border: 1px solid var(--color-rule);
  border-radius: 10px;
  overflow: hidden;
  min-width: 0;
  transition:
    transform var(--dur-micro) var(--ease-out),
    opacity var(--dur-micro) var(--ease-out);
}
.library-card:hover {
  box-shadow: none;
}
.library-preview {
  width: 100%;
  border: 0;
  padding: 0;
  position: relative;
  background: var(--color-paper-2);
  display: block;
}
.library-preview .resume-thumbnail {
  height: 215px;
  padding-top: var(--space-lg);
}
.library-preview .thumbnail-paper {
  transform: scale(1.25);
  transform-origin: top center;
}
.library-card-body {
  padding: var(--space-md) var(--space-md);
}
.library-card-body h2 {
  font-size: var(--text-sm);
  font-weight: 550;
  color: var(--color-ink-2);
  line-height: 1.7;
  overflow-wrap: anywhere;
}
.library-card-body > p {
  font-size: var(--text-xs);
  color: var(--color-muted);
  margin-top: var(--space-xs);
  line-height: 1.8;
}
.completion-row {
  height: 4px;
  background: var(--color-paper-2);
  border-radius: 4px;
  overflow: hidden;
  margin: var(--space-md) 0 var(--space-xs);
}
.completion-row > span {
  height: 100%;
  background: var(--color-accent);
  border-radius: 4px;
  display: block;
  transition:
    transform var(--dur-micro) var(--ease-out),
    opacity var(--dur-micro) var(--ease-out);
}
.library-card-body > small {
  font-size: var(--text-xs);
  color: var(--color-muted);
}
.card-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2xs);
  flex-wrap: wrap;
  margin-top: var(--space-md);
}
.card-actions > .base-button {
  margin-right: auto;
}
.card-actions .icon-button {
  width: 28px;
  height: 30px;
}
.card-actions > small {
  margin-right: auto;
  font-size: var(--text-xs);
  color: var(--color-muted);
}
.danger-icon:hover {
  color: var(--color-error);
  background: var(--color-paper);
}
.danger-text {
  color: var(--color-error) !important;
}
.danger-button {
  background: var(--color-error) !important !important;
  border-color: var(--color-error) !important !important;
  color: var(--color-accent-ink) !important !important;
}
.app-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
