  align-items: center;
  gap: var(--space-xs);
  color: var(--color-muted);
  font-size: var(--text-sm);
}
.auth-form {
  width: 100%;
  max-width: 360px;
}
.auth-form > h2 {
  font-size: 29px;
  font-weight: 550;
  color: var(--color-ink-2);
  margin: var(--space-lg) 0 var(--space-sm);
}
.auth-form > p:not(.auth-switch) {
