}
.auth-switch {
  text-align: center;
  font-size: var(--text-sm);
  line-height: 1.9;
  color: var(--color-muted);
  margin-top: var(--space-5);
}
.auth-switch a {
  color: var(--color-ink-2);
  margin-left: var(--space-xs);
}
.auth-form .demo-notice {
  font-size: var(--text-xs);
  color: var(--color-muted);
  line-height: 1.9;
}
.auth-form .demo-notice > svg {
