/* ===== 简历编辑页布局调整（删除 AI 助手后）===== */
@media (min-width: 701px) {
  .editor-grid {
    grid-template-columns: minmax(400px, 1.25fr) minmax(0, 1fr);
  }
  .editor-controls {
    max-height: calc(100dvh - 220px);
    overflow-x: hidden;
    overflow-y: auto;
    padding: 0 6px 16px 0;
  }
  .editor-preview {
    max-height: calc(100dvh - 220px);
    overflow-y: auto;
    overflow-x: hidden;
  }
  .editor-tabs {
    position: sticky;
    top: 0;
    z-index: 20;
    background: var(--color-paper);
    padding-top: 4px;
    padding-bottom: 8px;
  }
}

/* ===== 简历编辑「内容」分块卡片 ===== */
.editor-controls {
  background: none;
  border: none;
  box-shadow: none;
}
.editor-cards {
  border: none;
}
.editor-cards .el-collapse-item {
  background: #FFFFFF;
  border: 1px solid var(--color-rule);
  border-radius: 14px;
  margin-bottom: 14px;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(33, 37, 41, 0.04);
}
.editor-cards .el-collapse-item__header {
  display: flex;
  align-items: center;
  height: auto;
  min-height: 54px;
  padding: 14px 20px;
  line-height: 1.5;
  background: none;
  border-bottom: none;
  font-size: 16px;
  font-weight: 600;
  color: #212529;
}
.editor-cards .el-collapse-item__wrap {
  border-bottom: none;
}
.editor-cards .el-collapse-item__content {
  padding: 0 20px 20px;
}
.editor-cards .el-collapse-item__arrow {
  display: none;
}
.editor-cards .el-collapse-item__header::after {
  content: '+';
  font-size: 22px;
  font-weight: 400;
  line-height: 1;
  color: var(--el-color-primary);
  margin-left: auto;
  padding-left: 12px;
}
.editor-cards .el-collapse-item.is-active .el-collapse-item__header::after {
  content: '−';
}
.editor-card-add {
  width: 100%;
  height: 40px;
  border-radius: 10px;
}
